```java
@RestController
public class AdminController {
    private boolean isAdminAuthenticated = false;

    @PostMapping("/admin/execute")
    public ResponseEntity<String> executeAdminTask(@RequestHeader("Auth-Token") String token) {
        if (tokenManager.isValidAdminToken(token)) {
            this.isAdminAuthenticated = true;
        }

        if (this.isAdminAuthenticated) {
            // 다른 사용자의 요청이 동시에 들어올 경우 권한이 공유되는 TOCTOU 취약점
            systemService.executeCriticalTask();
            this.isAdminAuthenticated = false;
            return ResponseEntity.ok("Task executed");
        }
        return ResponseEntity.status(403).body("Access Denied");
    }
}
```
